function stopVideo(){lessonMediaCleanup?.();lessonMediaCleanup=null;if(studyMessageHandler){window.removeEventListener('message',studyMessageHandler);studyMessageHandler=null;}if(courseKeyHandler){document.removeEventListener('keydown',courseKeyHandler);courseKeyHandler=null;}if(originalGameMessageHandler){window.removeEventListener('message',originalGameMessageHandler);originalGameMessageHandler=null;}if(slideMessageHandler){window.removeEventListener('message',slideMessageHandler);slideMessageHandler=null;}dialog.querySelectorAll('video').forEach(v=>{v.onpause?.();v.onpause=null;v.ontimeupdate=null;v.onended=null;v.onerror=null;v.onloadedmetadata=null;v.onplay=null;v.pause();v.removeAttribute('src');v.load();});}
function open(kind,html){if(tutorial.active)stopTutorial();vnCleanup?.();vnCleanup=null;scheduleTutorial();stopVideo();dialog.classList.remove('todo-dialog','mentor-picker','course-zoomed','study-dialog','notebook-dialog','course-dialog','original-game-dialog','vn-dialog','vn-choosing','course-player');if(!dialog.open){returnFocus=document.activeElement;dialog.showModal();}$('dialog-kind').textContent=kind;$('dialog-body').innerHTML=html;$('dialog-body').classList.remove('reveal');void $('dialog-body').offsetWidth;$('dialog-body').classList.add('reveal');dialog.scrollTop=0;}
