function installHoverLights(host,helper){
 const actorShapes={Thomas:'52,0 70,2 81,12 77,22 70,27 91,35 100,62 94,99 7,99 0,68 6,47 17,34 43,26 40,15 46,4',Brendan:'40,0 62,1 76,10 75,23 66,28 90,35 100,53 96,78 91,99 4,99 0,51 11,34 31,27 25,17 26,10',William:'36,0 56,2 67,12 68,18 60,27 81,32 96,46 100,67 94,88 86,99 5,99 0,63 3,43 18,31 32,26 25,16 27,7'};
 const points=button=>button.classList.contains('person')?actorShapes[helper]:button.classList.contains('computer-hotspot')?'2,5 71,1 80,63 99,82 28,99 5,79':button.id==='scene-notebook'?'17,5 84,1 99,94 1,99':button.classList.contains('puzzle-hotspot')?'8,1 99,6 96,99 1,90':button.id==='scene-help'?(helper==='Thomas'?'1,35 75,1 99,55 68,99 3,69':'2,25 90,1 99,85 5,99'):button.id==='scene-revision'?'1,29 25,1 92,11 99,37 95,99 3,84':'0,0 100,0 100,100 0,100';
 const asPairs=shape=>shape.split(' ').map(p=>p.split(',').map(Number));
 const asCss=shape=>shape.map(([x,y])=>x+'% '+y+'%').join(',');
 for(const button of host.querySelectorAll('.scene-item')){const shape=asPairs(points(button));let all=[...shape,shape[0]];const blockers=button.id==='scene-mindmap'?[host.querySelector('.person')]:button.classList.contains('person')?[host.querySelector('.computer-hotspot'),host.querySelector('.puzzle-hotspot')]:[];for(const other of blockers.filter(Boolean)){const rect=el=>[parseFloat(el.style.left),parseFloat(el.style.top),parseFloat(el.style.width),parseFloat(el.style.height)];const [x,y,w,h]=rect(button),[ox,oy,ow,oh]=rect(other),cut=asPairs(points(other)).map(([px,py])=>[(ox+px*ow/100-x)/w*100,(oy+py*oh/100-y)/h*100]);all.push(...cut,cut[0],shape[0]);}const light=document.createElement('span');light.className='hover-light';light.setAttribute('aria-hidden','true');light.style.clipPath='polygon(evenodd,'+asCss(all)+')';button.append(light);}
}
function render(){
 const learned=availableNotionIds(state);
 const m=current();viewRoom=m.room;const room=rooms[m.room],layout=sceneLayouts[m.room];const background=$('background'),sceneSource=room.sceneImage||room.image;if(background.getAttribute('src')!==sceneSource){background.style.visibility='hidden';background.onload=()=>{background.style.visibility='visible';};background.src=sceneSource;if(background.complete&&background.naturalWidth)background.style.visibility='visible';}$('background').alt=`${room.helper} dans ${room.name.toLowerCase()}, un lieu illustré baigné de soleil.`;
 $('room-label').textContent=room.name;
 $('map').innerHTML=icon('map')+'<span class="tool-text">Les lieux</span>';$('map').setAttribute('aria-label','Le parcours');
 $('journal').innerHTML=icon('book')+`<span class="tool-text">Carnet <span aria-hidden="true">·</span> ${learned.length}/39</span>`;$('journal').setAttribute('aria-label',`Carnet, ${learned.length} notions disponibles sur 39`);
 $('help').innerHTML=icon('help');
 $('courses').innerHTML=icon('book')+'<span class="tool-text">Les cours</span>';
 let objective=!started?'Découvrir le parcours':state.finished?'Parcours terminé':state.solved?'La partie est terminée':!state.talked.includes(m.id)?`Parler à ${m.helper}`:'Explorer les objets de la pièce';
 $('objective').innerHTML=icon('search')+`<div><small>${state.finished?'Parcours terminé':`Partie ${String(state.mission+1).padStart(2,'0')} sur 10`}</small><strong>${objective}</strong></div>`;
 const isCurrent=viewRoom===m.room;
 const hotspots=$('hotspots');hotspots.replaceChildren();
 if(started){
  const people=[{helper:'Thomas',rect:[10,9,20,62]},{helper:'Brendan',rect:[10,9,20,62]},{helper:'William',rect:[10,9,20,62]}];
  for(const entry of people.filter(person=>person.helper===m.helper)){const person=document.createElement('button');person.id='scene-person';person.className='hotspot person scene-item classroom-person';person.setAttribute('aria-label','Parler à '+entry.helper);positionInScene(person,entry.rect);person.onclick=()=>{const index=entry.helper===m.helper?state.mission:missions.findLastIndex((lesson,i)=>lesson.helper===entry.helper&&canOpenCourse(state,i));courses(null,index<0?missions.findIndex(lesson=>lesson.helper===entry.helper):index);};hotspots.append(person);}
  const computer=document.createElement('button');computer.className='hotspot computer-hotspot scene-item';computer.setAttribute('aria-label','Ordinateur : reprendre le cours');positionInScene(computer,layout.computer);computer.onclick=()=>state.talked.includes(m.id)?playCourse(null,state.mission):talk();hotspots.append(computer);
  const notebook=document.createElement('button');notebook.id='scene-notebook';notebook.className='hotspot object scene-item notebook-hotspot';notebook.setAttribute('aria-label','Cahier : notions clés et mes notes');positionInScene(notebook,layout.notebook);notebook.onclick=()=>journal();hotspots.append(notebook);

  const box=document.createElement('button');box.id='scene-revision';box.className='hotspot scene-item hub-prop revision-box';box.setAttribute('aria-label','Boîte de fiches : état de l’apprentissage et révisions');positionInScene(box,layout.revision);box.onclick=()=>study('reviser');hotspots.append(box);
  if(!state.finished){m.puzzles.forEach((p,i)=>{const site=layout.puzzles[i];const b=document.createElement('button');b.className='hotspot scene-item puzzle-hotspot';b.dataset.puzzle=String(i);b.setAttribute('aria-label','Tableau d’exercice : '+p.title);positionInScene(b,site.rect);b.onclick=()=>explorePuzzle(i);hotspots.append(b);});}

 }
 if(started)installHoverLights(hotspots,m.helper);
 $('welcome').hidden=started;
 if(!started){$('welcome').innerHTML=`<div class="welcome-content"><span class="welcome-eyebrow">COMPRENDRE L’IA, À VOTRE RYTHME</span><h1>RI7,<br><em>certification VIA</em></h1><p>Des cours interactifs, des exercices et vos notes.<br>Trois tuteurs pour comprendre, pratiquer et retenir.</p><div class="welcome-actions"><button class="primary" id="start">${state.talked.length?'Reprendre mon parcours':'Commencer le parcours'} ${icon('arrow')}</button><button class="welcome-guide" id="welcome-help">Comment jouer ?</button></div><span class="welcome-save">${state.talked.length?'Partie '+(state.mission+1)+' sur 10 · Avec '+m.helper+' · Progression conservée':'10 chapitres · 39 notions · À votre rythme'}</span><span class="welcome-signature">Comprendre. Pratiquer. Retenir.</span></div>`;
 $('welcome-help').onclick=help;
 $('start').onclick=async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Entrée dans la classe…';const welcome=$('welcome'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;try{await $('background').decode();}catch{}const animation=welcome.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(1.025)'}],{duration:reduced?0:650,easing:'ease-in-out',fill:'forwards'});await animation.finished;const firstVisit=!tutorial.seen&&!state.talked.length;started=true;render();animation.cancel();if(firstVisit)tutorialIntro();else{document.querySelector('.person')?.focus({preventScroll:true});scheduleTutorial();}};
 }

 $('scene-message').innerHTML=!started?'':state.finished?'<strong>Diagnostic terminé</strong>Le carnet conserve vos notes et les notions du cours.':`<strong>${esc(m.title)}</strong>${state.solved?'Les notions sont validées. Retrouvez votre interlocuteur pour poursuivre le parcours.':!state.talked.includes(m.id)?`${m.helper} vous présente l’objectif de cette partie.`:'Parcourez le cours puis vérifiez vos connaissances avec le jeu de cette partie.'}`;
 $('progress').innerHTML=`<span class="dots" aria-hidden="true">${'●'.repeat(state.completed.length)}${'○'.repeat(10-state.completed.length)}</span>${state.completed.length} / 10 chapitres terminés`;
 renderLearningGuide();scheduleTutorial();
}
function explorePuzzle(index){
 const m=current(),p=m.puzzles[index],site=sceneLayouts[m.room].puzzles[index];
 if(state.solved)return missionDone();
 if(index===state.step)return puzzle();
 let text;
 if(index<state.step)text=p.explanation;
 
 else text=`Cette partie du mécanisme dépend d’une déduction précédente : « ${m.puzzles[state.step].title} ». Explorez les autres objets de la pièce pour la résoudre.`;
 open('Un objet attire votre attention',`<h2 id="dialog-title">${esc(site.place)}</h2><p>${esc(text)}</p><div class="dialog-actions"><button class="secondary" id="object-course">Consulter le cours</button><button class="primary" id="object-return">Continuer à explorer</button></div>`);$('object-course').onclick=()=>courses();$('object-return').onclick=close;
}
function renderLearningGuide(){
 const m=current(),talked=state.talked.includes(m.id),evidence=state.evidence.includes(m.id);
 const steps=[['1',`Parler à ${m.helper}`,talked],['2','Parcourir les slides interactives',courseDone(state,state.mission)],['3','Réussir le jeu Ri7',state.solved]];
 const next=state.finished?'Enquête terminée : les cours restent disponibles.':!talked?`Commencez par parler à ${m.helper}.`:state.solved?'Jeu réussi : terminez les slides pour recevoir la suite.':`Examinez l’objet de la pièce pour ouvrir « ${m.puzzles[0].title} ».`;

 $('learning-guide').innerHTML=`<div class="learning-guide-heading"><strong>Partie ${state.mission+1} · ${esc(m.title)}</strong><span>${esc(next)}</span></div><ol class="learning-steps">${steps.map(([n,label,done])=>`<li class="${done?'done':''}"><span>${done?'✓':n}</span>${esc(label)}${n==='2'?'<small>les médias sont facultatifs</small>':''}</li>`).join('')}</ol><div class="learning-tools"><button id="lesson-current" class="guide-button">${icon('book')}Cours du chapitre</button><button id="definitions-current" class="guide-button">Définitions</button><button id="find-clues" class="guide-button">${icon('search')}Trouver le jeu</button><button id="problem-order" class="guide-button">Ordre des exercices</button></div>`;
 $('lesson-current').onclick=()=>courses();$('definitions-current').onclick=()=>journal(m.terms);$('find-clues').onclick=findClues;$('problem-order').onclick=problemOrder;
}
function definitionRows(ids){return ids.map(id=>{const t=termById[id];return `<article class="journal-row"><h3>${esc(t.name)}</h3><p>${esc(t.definition)}</p><p class="example">Exemple : ${esc(t.example)}</p></article>`;}).join('');}
function courses(back=null,partIndex=state.mission,resume=false){
 const m=missions[partIndex],story=mentorStories[partIndex],allowed=canOpenCourse(state,partIndex);
 const done=courseDone(state,partIndex),solved=state.completed.includes(m.id),alreadyTalked=state.talked.includes(m.id);
 const introKey=m.id+':intro',phaseKey=m.id+':'+(!allowed?'locked':done?solved?'complete':'game':'lesson');
 if(allowed&&partIndex===state.mission&&!state.finished)commit({type:'talk'});
 let speech=!allowed?'Je garde cette leçon pour la suite. Terminez les slides et les exercices des parties précédentes ; nous avancerons ensuite ensemble.':!done?'Le cours vous présente les notions ; l’exercice vous permet de les réutiliser. Je reste disponible si un point vous semble difficile.':!solved?story.after:'Cette partie est terminée. Faisons le point sur ce que vous retenez, ou passons à la suivante.';
 open(`Conversation avec ${m.helper}`,`<img class="vn-backdrop" src="${rooms[m.room].sceneImage||rooms[m.room].image}" alt=""><img class="vn-focus" src="${rooms[m.room].sceneImage||rooms[m.room].image}" alt="${m.helper} en gros plan dans ${esc(rooms[m.room].name)}"><div class="vn-shade"></div><span class="vn-scene-label">${esc(m.helper)} · ${esc(story.role)} · Partie ${partIndex+1}</span><button class="vn-skip" id="vn-skip">Passer aux choix</button><div class="vn-choices" aria-label="Vos réponses" hidden>${allowed?`<button class="primary" id="mentor-lesson">${done?'Revoir la leçon avec '+m.helper:'Suivre le cours avec '+m.helper}</button><button class="secondary" id="mentor-help">Revoir une notion avec moi</button><button class="secondary" id="mentor-check">Vérifier ma compréhension</button><button class="secondary" id="see-terms">Notions clés & mes notes</button>`:'<button class="primary" id="mentor-current">Retrouver la leçon en cours</button>'}<button class="secondary" id="explore">${back?'Revenir à l’exercice':'Retourner dans la pièce'}</button>${allowed&&done&&solved&&partIndex===state.mission&&!state.finished?'<button class="primary" id="mentor-continue">Partie suivante</button>':''}</div><section class="vn-dialogue" aria-label="Dialogue"><div class="vn-name"><h2 id="dialog-title">${m.helper}</h2></div><button id="vn-advance" class="vn-advance" aria-label="Afficher le texte complet"><p id="vn-text" aria-hidden="true"></p><span class="sr-only" id="vn-read" aria-live="polite"></span></button><div class="vn-footline"><span id="vn-counter"></span><span id="vn-prompt"></span></div></section>`);
 dialog.dataset.speaker=m.helper;dialog.style.setProperty('--speaker-x','23%');
 const intro=allowed&&!resume&&!dialogueProgress[introKey]?.complete&&(!alreadyTalked||!!dialogueProgress[introKey]);
 const segments=intro?[story.scene,'L’objectif de cette partie : '+story.goal]:[allowed&&!done?'Vous pouvez reprendre les slides là où vous vous êtes arrêté. Votre progression est conservée ; le jeu de cette partie vous attendra après le cours.':speech];
 const progressKey=intro?introKey:phaseKey,signature=JSON.stringify(segments),savedDialogue=dialogueProgress[progressKey];
 if(!savedDialogue||savedDialogue.signature!==signature){dialogueProgress[progressKey]={signature,page:0,complete:false};saveDialogueProgress();}
 dialog.classList.add('vn-dialog');vnCleanup=mountVisualNovel(dialog,segments,{startPage:savedDialogue?.signature===signature?savedDialogue.page:0,onProgress:page=>{dialogueProgress[progressKey]={signature,page,complete:dialogueProgress[progressKey]?.complete||false};saveDialogueProgress();},onComplete:()=>{dialogueProgress[progressKey]={signature,page:999,complete:true};if(intro)dialogueProgress[phaseKey]={signature:JSON.stringify([allowed&&!done?'Vous pouvez reprendre les slides là où vous vous êtes arrêté. Votre progression est conservée ; le jeu de cette partie vous attendra après le cours.':speech]),page:999,complete:true};saveDialogueProgress();}});
 $('explore').onclick=back||close;
 if(allowed){$('mentor-lesson').onclick=()=>playCourse(back,partIndex);$('mentor-help').onclick=()=>mentorSupport(partIndex,back);$('mentor-check').onclick=()=>mentorCheck(partIndex,back);$('see-terms').onclick=()=>journal(m.terms,()=>courses(back,partIndex,true));}
 else $('mentor-current').onclick=()=>courses(back,Math.max(0,courseParts.findIndex((p,i)=>!courseDone(state,i)||!state.completed.includes(missions[i].id))));
 if($('mentor-continue'))$('mentor-continue').onclick=()=>{commit({type:'next'});viewRoom=current().room;selected=[];render();state.finished?finish():talk();};
}

function mentorActivity(partIndex,text,actions){
 const m=missions[partIndex],story=mentorStories[partIndex],image=rooms[m.room].sceneImage;
 open('Échange avec '+m.helper,`<img class="vn-backdrop" src="${image}" alt=""><img class="vn-focus" src="${image}" alt="${m.helper} dans la classe"><div class="vn-shade"></div><span class="vn-scene-label">${m.helper} · ${esc(story.role)}</span><button class="vn-skip" id="vn-skip">Passer aux choix</button><div class="vn-choices" hidden>${actions.map((a,i)=>'<button class="'+(i===0?'primary':'secondary')+'" data-mentor-action="'+i+'">'+esc(a.label)+'</button>').join('')}</div><section class="vn-dialogue"><div class="vn-name"><h2 id="dialog-title">${m.helper}</h2></div><button id="vn-advance" class="vn-advance"><p id="vn-text" aria-hidden="true"></p><span class="sr-only" id="vn-read" aria-live="polite"></span></button><div class="vn-footline"><span id="vn-counter"></span><span id="vn-prompt"></span></div></section>`);dialog.classList.add('vn-dialog');dialog.dataset.speaker=m.helper;dialog.style.setProperty('--speaker-x','23%');vnCleanup=mountVisualNovel(dialog,[text]);for(const button of dialog.querySelectorAll('[data-mentor-action]'))button.onclick=actions[Number(button.dataset.mentorAction)].run;
}
function mentorSupport(partIndex,back=null){mentorTopicPicker(partIndex,back);}
function mentorTopicPicker(partIndex,back=null,page=0,scope='part'){
 const ids=scope==='part'?missions[partIndex].terms:[...new Set(missions.filter((m,i)=>i<=state.mission&&canOpenCourse(state,i)).flatMap(m=>m.terms))];
 const pages=Math.max(1,Math.ceil(ids.length/4)),index=Math.min(page,pages-1);
 const actions=ids.slice(index*4,index*4+4).map(id=>({label:termById[id].name,run:()=>mentorTerm(partIndex,id,back,index,scope)}));
 if(index>0)actions.push({label:'← Notions précédentes',run:()=>mentorTopicPicker(partIndex,back,index-1,scope)});
 if(index<pages-1)actions.push({label:'Notions suivantes →',run:()=>mentorTopicPicker(partIndex,back,index+1,scope)});
 actions.push({label:scope==='part'?'Toutes mes notions accessibles':'Notions de cette partie',run:()=>mentorTopicPicker(partIndex,back,0,scope==='part'?'learned':'part')},{label:'Retour à la conversation',run:()=>courses(back,partIndex,true)});
 mentorActivity(partIndex,'Quelle notion souhaitez-vous revoir ?',actions);dialog.classList.add('mentor-picker');dialog.querySelector('#vn-skip').click();$('vn-text').textContent='Quelle notion souhaitez-vous revoir ?';$('vn-read').textContent='Quelle notion souhaitez-vous revoir ?';$('vn-counter').textContent=(scope==='part'?'Cette partie':'Notions accessibles')+' · '+(index+1)+' / '+pages;
}
