 dialog.classList.add('course-dialog','course-player');dialog.classList.toggle('course-zoomed',courseZoomed);$('course-zoom').setAttribute('aria-pressed',String(courseZoomed));$('course-zoom').textContent=courseZoomed?'A−':'A+';$('course-zoom').onclick=()=>{courseZoomed=!courseZoomed;dialog.classList.toggle('course-zoomed',courseZoomed);$('course-zoom').setAttribute('aria-pressed',String(courseZoomed));$('course-zoom').setAttribute('aria-label',courseZoomed?'Afficher toute la slide':'Agrandir la slide');$('course-zoom').textContent=courseZoomed?'A−':'A+';window.dispatchEvent(new Event('resize'));};
 const frame=$('interactive-slide'),video=$('lesson-video'),drawer=$('course-tools');let lastSaved=0,frameReady=false,navigationPending=false,queuedDirection=0;
