  let direction=['ArrowRight','ArrowDown','PageDown'].includes(e.key)?1:['ArrowLeft','ArrowUp','PageUp'].includes(e.key)?-1:0;
  if(e.key===' '&&!e.target.closest('button,a,video'))direction=1;
  const command={p:'media-play',m:'media-mute',v:'media-visibility',c:'media-captions'}[e.key.toLowerCase()];
