 const persistMedia=()=>{try{localStorage.setItem('ri7-media-preferences',JSON.stringify(mediaPreferences));}catch{}};
 const mediaLabels=()=>{$('lesson-caption').hidden=!mediaPreferences.captions;$('course-captions').setAttribute('aria-pressed',String(mediaPreferences.captions));$('course-captions').setAttribute('aria-label',mediaPreferences.captions?'Désactiver les sous-titres':'Activer les sous-titres');$('media-captions').textContent=mediaPreferences.captions?'Désactiver les sous-titres':'Activer les sous-titres';$('media-captions').setAttribute('aria-pressed',String(mediaPreferences.captions));video.hidden=!mediaPreferences.visible;video.closest('figure').hidden=!mediaPreferences.visible;video.muted=mediaPreferences.muted;$('media-visibility').textContent=mediaPreferences.visible?'Masquer la vidéo · audio seul':'Afficher la vidéo';$('media-visibility').setAttribute('aria-pressed',String(mediaPreferences.visible));$('media-mute').textContent=mediaPreferences.muted?'Activer le son':'Couper le son';$('media-mute').setAttribute('aria-pressed',String(mediaPreferences.muted));$('media-play').textContent=video.paused?'Lancer l’accompagnement':'Arrêter l’accompagnement';};
