 const loader=$('lesson-media-loading'),message=$('lesson-media-message'),retry=$('lesson-media-retry'),figure=video.closest('figure');let firstPicture=false,controller=null;
 controller=mountLessonMedia({video,url:slide.video,resumeAt:state.videoPositions[slide.id]||0,preferences:mediaPreferences,onPosition:time=>commit({type:'video-position',slideId:slide.id,time}),onEnded:()=>commit({type:'video-ended',slideId:slide.id}),onCaption:time=>{const caption=slide.captions.find(c=>time>=c.start&&time<c.end);if($('lesson-caption'))$('lesson-caption').textContent=caption?.text||'';},onChange:()=>{if(video.isConnected&&$('lesson-video')===video)mediaLabels();},onState:(status,text)=>{if(!video.isConnected||$('lesson-video')!==video)return;if(status==='ready')firstPicture=true;figure.dataset.mediaReady=String(firstPicture);loader.hidden=status==='ready';message.textContent=text;retry.hidden=!['error','blocked','paused'].includes(status);retry.textContent=['blocked','paused'].includes(status)?'Lancer':'Réessayer';figure.dataset.mediaState=status;if($('media-status'))$('media-status').textContent=status==='ready'?'':text;}});
