function findClues(){const m=current();started=true;viewRoom=m.room;render();close();const target=document.querySelector('[data-puzzle="0"]');target?.focus();target?.classList.add('highlight-clue');}
function problemOrder(){
 const m=current();open('La progression du chapitre',`<h2 id="dialog-title">Dans quel ordre avancer ?</h2><p>Chaque chapitre suit trois étapes : parler au guide, parcourir les slides et réussir le jeu Ri7 accessible sur un objet de la pièce. Le cours reste consultable pendant une exercice.</p>${m.puzzles.map((p,i)=>`<article class="journal-row problem-row"><small>${i<state.step?'Résolue':i===state.step&&!state.solved?'Prochaine exercice':'À venir'} · ${i+1}/${m.puzzles.length}</small><h3>${esc(p.title)}</h3><p>${esc(p.scene)}</p></article>`).join('')}<p class="small-note">Suivez les consignes du jeu original Ri7 : association par clic ou glisser-déposer, choix de notions, carte à compléter ou étapes à déplacer avec les poignées et les boutons Monter / Descendre. Le cours et les définitions restent disponibles.</p><div class="dialog-actions"><button class="primary" id="order-close">Retour à la classe</button></div>`);$('order-close').onclick=close;
}
function talk(){courses(null,state.mission);}
function recap(helper){const ids=missions.filter(m=>m.helper===helper&&state.talked.includes(m.id)).flatMap(m=>m.terms);open(`Conversation avec ${helper}`,`<h2 id="dialog-title">Ce que nous avons découvert</h2><p>Vous pouvez retrouver nos observations et le vocabulaire dans le carnet. Le chapitre en cours reste disponible depuis le plan des lieux.</p>${termsMarkup([...new Set(ids)])}<div class="dialog-actions"><button class="primary" id="recap-journal">Consulter le carnet</button></div>`);$('recap-journal').onclick=()=>journal(ids);}
function originalPuzzle(){
 const m=current(),p=m.puzzles[state.step];if(state.solved)return missionDone();if(!state.talked.includes(m.id))return talk();
 const nonce=crypto.randomUUID();
 open('Jeu original Ri7 · '+m.helper,`<h2 id="dialog-title">${esc(p.title)}</h2><p class="original-game-note">Les règles, les questions et les interactions viennent de la fiche mémo Ri7. Réussissez toutes les réponses de la partie pour valider ce chapitre. Une partie interrompue recommence ; un chapitre validé reste sauvegardé.</p><div class="original-game-stage"><iframe id="original-game-frame" title="Jeu Ri7 : ${esc(p.title)}" sandbox="allow-scripts" allow="fullscreen" allowfullscreen></iframe></div><div id="original-game-status" role="status">À vous de jouer.</div><div class="dialog-actions"><button class="secondary" id="original-game-course">Revoir le cours</button><button class="secondary" id="original-game-definitions">Définitions</button><button class="secondary" id="original-game-fullscreen">Agrandir le jeu</button><button class="primary" id="original-game-done" disabled>Conclure le chapitre</button></div>`);
 dialog.classList.add('original-game-dialog');const frame=$('original-game-frame');
 originalGameMessageHandler=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='ri7-original-game'||e.data.nonce!==nonce)return;const event=e.data.event;if(event?.type==='partie_terminee'&&event.jeu===p.original.game){if(event.score===event.total&&event.total>0){const result=commit({type:'original-game-complete',game:event.jeu,score:event.score,total:event.total});if(result.correct){$('original-game-status').textContent='Toutes les réponses sont correctes : jeu validé et sauvegardé.';$('original-game-done').disabled=false;}}else $('original-game-status').textContent='Partie terminée : '+event.score+' / '+event.total+'. Utilisez « Rejouer » dans le jeu pour réussir toutes les réponses.';}};
 window.addEventListener('message',originalGameMessageHandler);frame.srcdoc=originalGamesDocument.replace('/*CONFIG*/',JSON.stringify({...p.original,nonce}));
 $('original-game-course').onclick=()=>courses(()=>originalPuzzle());$('original-game-definitions').onclick=()=>journal(null,()=>originalPuzzle());$('original-game-fullscreen').onclick=()=>frame.parentElement.requestFullscreen?.().catch(()=>{});$('original-game-done').onclick=missionDone;
}
function puzzle(){if(current().puzzles[state.step]?.type==='original-game')return originalPuzzle();
 const m=current();if(state.solved)return missionDone();if(!state.talked.includes(m.id))return talk();
 const p=m.puzzles[state.step];let answer=[];hintLevel=0;
 open(`Partie ${state.mission+1} · Épreuve ${state.step+1} / ${m.puzzles.length}`,`<h2 id="dialog-title">${esc(p.title)}</h2><p class="puzzle-scene">${esc(p.scene)}</p>${p.type==='order'?'<p class="order-help">Cliquez les éléments dans l’ordre. Cliquez à nouveau pour retirer un élément.</p><div id="order-preview" class="order-preview">Votre reconstitution apparaîtra ici.</div>':''}<div id="options" class="options"></div><div id="answer-feedback" class="feedback" role="status"></div><div id="hint-text"></div><div class="dialog-actions"><button class="secondary" id="hint">Un indice</button><button class="secondary" id="puzzle-courses">Lire le cours</button><button class="secondary" id="puzzle-journal">Définitions</button><button class="primary" id="validate" disabled>Vérifier l’hypothèse ${icon('check')}</button></div>`);
 const displayOptions=()=>{
  $('options').innerHTML=p.options.map(o=>`<button class="option${answer.includes(o.id)?' selected':''}" data-option="${o.id}" aria-pressed="${answer.includes(o.id)}"><span class="number">${p.type==='order'?(answer.includes(o.id)?answer.indexOf(o.id)+1:'·'):(answer.includes(o.id)?'✓':'○')}</span><span>${esc(o.label)}</span></button>`).join('');
  for(const b of $('options').querySelectorAll('button'))b.onclick=()=>{const id=b.dataset.option;answer=p.type==='order'?(answer.includes(id)?answer.filter(x=>x!==id):[...answer,id]):[id];displayOptions();};
  if(p.type==='order')$('order-preview').textContent=answer.length?answer.map((id,i)=>`${i+1}. ${p.options.find(o=>o.id===id).label}`).join(' → '):'Votre reconstitution apparaîtra ici.';
  $('validate').disabled=p.type==='order'?answer.length!==p.options.length:answer.length!==1;
 };
 displayOptions();
 $('hint').onclick=()=>{hintLevel=Math.min(3,hintLevel+1);const hints=[p.hint,`Les notions utiles : ${m.terms.map(id=>termById[id].name).join(', ')}.`,p.type==='order'?`Le premier élément est : « ${p.options.find(o=>o.id===p.solution[0]).label} ». Reprenez ensuite les relations de cause à effet.`:`Cherchez l’hypothèse qui correspond à cette observation : ${p.hint}`];$('hint-text').innerHTML=`<div class="hint">Indice ${hintLevel}/3 — ${esc(hints[hintLevel-1])}</div>`;$('hint').textContent=hintLevel===3?'Indice complet':'Un autre indice';};
 $('puzzle-journal').onclick=()=>journal(m.terms,()=>puzzle());
 $('puzzle-courses').onclick=()=>courses(()=>puzzle());
 $('validate').onclick=()=>{const r=commit({type:'answer',answer});const feedback=$('answer-feedback');feedback.textContent=r.message;feedback.className='feedback'+(r.correct?'':' wrong');if(r.correct){for(const b of $('options').querySelectorAll('button'))b.disabled=true;$('hint').disabled=true;$('puzzle-journal').disabled=true;$('puzzle-courses').disabled=true;$('validate').textContent=state.solved?'Conclure ce chapitre':'Retourner explorer la pièce';$('validate').onclick=()=>state.solved?missionDone():close();}feedback.scrollIntoView({block:'nearest',behavior:'smooth'});};
}
function missionDone(){const m=current();open('Partie terminée',`<h2 id="dialog-title">Contrôle des notions validé.</h2><p>${esc(mentorStories[state.mission].evidence)}</p><p>${esc(m.puzzles.at(-1).explanation)}</p><div class="progress-track"><span style="width:${state.completed.length*10}%"></span></div><p class="small-note">${state.completed.length} chapitre${state.completed.length>1?'s':''} sur 10 résolu${state.completed.length>1?'s':''}. Vocabulaire réutilisé dans ce chapitre. Pour poursuivre, parcourez aussi toutes les slides précédentes et celles de ce chapitre :</p>${termsMarkup(m.terms)}<div class="dialog-actions"><button class="secondary" id="done-mentor">Faire le point avec ${m.helper}</button><button class="secondary" id="done-journal">Mon carnet</button><button class="secondary" id="done-course">Slides du chapitre</button><button class="primary" id="next-mission" ${courseParts.slice(0,state.mission+1).every((p,i)=>courseDone(state,i))?'':'disabled'}>${state.mission===9?'Terminer le parcours':'Partie suivante'} ${icon('arrow')}</button></div>`);$('done-mentor').onclick=()=>mentorCheck(state.mission,missionDone);$('done-course').onclick=()=>courses(null,courseParts.findIndex((p,i)=>i<=state.mission&&!courseDone(state,i))<0?state.mission:courseParts.findIndex((p,i)=>i<=state.mission&&!courseDone(state,i)));$('done-journal').onclick=()=>journal(m.terms,missionDone);$('next-mission').onclick=()=>{commit({type:'next'});viewRoom=current().room;selected=[];render();state.finished?finish():talk();};}
function finish(){open('Parcours terminé',`<h2 id="dialog-title">Vous avez terminé les dix parties.</h2><p>Avec Thomas, vous avez posé les bases de l’IA générative. Brendan vous a accompagné dans la fabrication des modèles et des assistants. William vous a aidé à comprendre leur utilisation et leurs limites.</p><div class="report-stat">39 notions</div><p>Continuez à les revoir dans votre carnet et dans les boîtes de révision. Les jeux originaux portent sur les 34 notions de la fiche mémo ; les cinq notions complémentaires restent accessibles dans le cours.</p><div class="dialog-actions"><button class="secondary" id="finish-map">Revoir le parcours</button><button class="primary" id="finish-journal">Ouvrir mes notes</button></div>`);$('finish-map').onclick=map;$('finish-journal').onclick=()=>journal();}

function study(mode='reviser',back=null){
 let stored=null;try{stored=JSON.parse(localStorage.getItem('ri7-study-v1'));}catch{}
 const nonce=crypto.randomUUID();open('Mémoire & relations · Ri7',`<h2 id="dialog-title" class="course-sr">Boîtes de révision & cartes mentales</h2><iframe id="study-frame" title="Boîtes et cartes mentales originales Ri7" sandbox="allow-scripts"></iframe><div class="study-bottom"><span id="study-status" role="status">Révisions personnelles · indépendantes des chapitres du jeu</span><button id="study-back" class="secondary">${back?'Retour au carnet':'Retour dans la classe'}</button></div>`);dialog.classList.add('study-dialog');const frame=$('study-frame');
 studyMessageHandler=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='ri7-study-state'||e.data.nonce!==nonce)return;const value=e.data.state;if(value?.version!==2||!value.cartes||typeof value.cartes!=='object'||Array.isArray(value.cartes)||!Array.isArray(value.joursDeRevision)||!value.joursDeRevision.every(d=>typeof d==='string')||typeof value.reglages?.son!=='boolean')return;for(const [id,card] of Object.entries(value.cartes)){if(!studyCardIds.includes(id)||!card||!Number.isInteger(card.boite)||card.boite<0||card.boite>5||!Number.isInteger(card.nbVues)||card.nbVues<0||![card.vueLe,card.depuis].every(d=>d===null||typeof d==='string'))return;}try{localStorage.setItem('ri7-study-v1',JSON.stringify(value));$('study-status').textContent='✓ État des boîtes enregistré sur cet appareil';}catch{$('study-status').textContent='Enregistrement indisponible dans ce navigateur';}};
 window.addEventListener('message',studyMessageHandler);frame.srcdoc=studyDocument.replace('/*STUDY_CONFIG*/',()=>JSON.stringify({mode,state:stored,nonce}).replaceAll('<','\\u003c'));$('study-back').onclick=back||close;
}
function journal(ids=null,back=null){
 open('Carnet personnel','<div id="notebook-root"></div>');dialog.classList.add('notebook-dialog');
 mountNotebook($('notebook-root'),{terms,visibleIds:availableNotionIds(state),ids,discovered:availableNotionIds(state),practiced:state.practiced,escape:esc,back,onBack:back||close,onStudy:mode=>study(mode,()=>journal(ids,back))});
}

function map(page=Math.floor(state.mission/5)){
 if(typeof page!=='number')page=Math.floor(state.mission/5);const m=current(),tasks=chapterTasks(state),next=tasks.find(t=>!t.done),done=tasks.filter(t=>t.done).length,completed=state.finished?10:state.mission;
 open('Progression & prochaines étapes',`<div class="todo-heading"><div><h2 id="dialog-title">Ma liste de tâches</h2><p>Partie ${state.mission+1} / 10 · ${esc(m.title)}</p></div><strong>${completed} / 10 parties terminées</strong></div><div class="todo-total" role="progressbar" aria-label="Parties terminées" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${completed}"><span style="width:${completed*10}%"></span></div><div class="todo-tabs"><button id="todo-show-tasks" aria-pressed="true">À faire</button><button id="todo-show-path" aria-pressed="false">Tout le parcours</button></div><div class="todo-layout" id="todo-layout" data-tab="tasks"><section class="todo-current"><div class="todo-section-title"><h3>${state.finished?'Tout est terminé':'Cette partie'}</h3><span>${done} / 4 étapes</span></div><ul class="todo-list">${tasks.map(task=>`<li class="todo-row ${task.done?'is-done':''}"><span class="todo-check" aria-label="${task.done?'Terminé':'À faire'}">${task.done?'✓':'○'}</span><div><strong>${esc(task.label)}</strong><p>${esc(task.detail)}</p></div><button class="secondary" data-todo-action="${task.action}" ${task.id==='next'&&!task.done&&!(courseParts.slice(0,state.mission+1).every((p,i)=>courseDone(state,i))&&state.solved)?'disabled':''}>${task.done?(task.id==='course'?'Revoir':task.id==='exercise'?'Bilan':task.id==='next'?'Terminé':'Revoir'):task.id==='next'?'Retrouver '+m.helper:'Ouvrir'}</button></li>`).join('')}</ul><div class="todo-next"><strong>${next?'Prochaine étape : '+esc(next.label):'Parcours terminé'}</strong><p>${next?'Les cases se cochent automatiquement, selon votre progression.':'Vous pouvez continuer à consulter les cours et à réviser.'}</p></div><div class="todo-optional"><span>Facultatif :</span><button id="todo-notes" class="text-button">Mes notes</button><button id="todo-revise" class="text-button">Réviser</button></div></section><section class="todo-path"><h3>Les dix parties</h3><div class="todo-chapters">${missions.slice(page*5,page*5+5).map((lesson,offset)=>{const i=page*5+offset,finished=i<state.mission||state.finished;return `<article class="todo-chapter"><span>${finished?'✓':String(i+1).padStart(2,'0')}</span><div><h4>${esc(lesson.title)}</h4><p>${lesson.helper} · ${finished?'Terminée':i===state.mission?'En cours':'À venir'}</p></div><button class="text-button" data-map-course="${i}" ${canOpenCourse(state,i)?'':'disabled'}>${canOpenCourse(state,i)?'Cours':'Verrouillé'}</button></article>`;}).join('')}</div><nav class="todo-pages" aria-label="Pages du parcours"><button id="todo-prev" class="secondary" ${page===0?'disabled':''}>←</button><span>${page+1} / 2</span><button id="todo-next-page" class="secondary" ${page===1?'disabled':''}>→</button></nav></section></div><div class="dialog-actions"><button id="todo-close" class="primary">Retour à la classe</button></div>`);dialog.classList.add('todo-dialog');
 const act=action=>{if(action==='talk'||action==='next')return state.finished?finish():courses();if(action==='exercise')return state.completed.includes(m.id)?missionDone():originalPuzzle();const pending=courseParts.findIndex((p,i)=>i<=state.mission&&!courseDone(state,i));return playCourse(null,pending<0?state.mission:pending);};
 for(const button of dialog.querySelectorAll('[data-todo-action]')){if(button.dataset.todoAction==='next'&&state.finished)button.disabled=true;button.onclick=()=>act(button.dataset.todoAction);}
 for(const button of dialog.querySelectorAll('[data-map-course]'))button.onclick=()=>playCourse(null,Number(button.dataset.mapCourse));
 $('todo-prev').onclick=()=>map(page-1);$('todo-next-page').onclick=()=>map(page+1);$('todo-close').onclick=close;$('todo-notes').onclick=()=>journal(null,()=>map(page));$('todo-revise').onclick=()=>study('reviser',()=>map(page));for(const tab of ['tasks','path'])$('todo-show-'+tab).onclick=()=>{$('todo-layout').dataset.tab=tab;for(const key of ['tasks','path'])$('todo-show-'+key).setAttribute('aria-pressed',String(key===tab));};
}

function review(i){const m=missions[i];open('Partie terminée · Relecture',`<h2 id="dialog-title">${esc(m.title)}</h2><p>${esc(m.evidence)}</p>${m.puzzles.map(p=>`<article class="journal-row"><h3>${esc(p.title)}</h3><p>${esc(p.explanation)}</p></article>`).join('')}${termsMarkup(m.terms)}<div class="dialog-actions"><button id="review-map" class="primary">Revenir au plan</button></div>`);$('review-map').onclick=map;}
const TUTORIAL_KEY='ri7-quick-tour-v2';
let tutorial={active:false,seen:false,index:0};try{const saved=JSON.parse(localStorage.getItem(TUTORIAL_KEY));if(saved?.seen)tutorial.seen=true;}catch{}
let tutorialFrame=null;
const quickTour=[
 {title:'Le cours',text:'Cliquez sur l’ordinateur « COURS ». Avancez avec les flèches ou le clavier. La vidéo est facultative.',target:'.computer-hotspot'},
 {title:'Les exercices',text:'La tablette « EXERCICES » ouvre le jeu du chapitre. Terminez le cours et le jeu, puis parlez au personnage pour passer à la suite.',target:'.puzzle-hotspot'},
 {title:'Vos notes',text:'Le cahier « NOTES » s’enrichit à mesure que vous parcourez les slides. Vous pouvez aussi y prendre des notes libres, enregistrées dans ce navigateur.',target:'#scene-notebook'},
 {title:'Pour réviser',text:'La boîte « RÉVISIONS » donne accès aux fiches de révision, aux cartes mentales et au suivi de votre apprentissage.',target:'#scene-revision'}
];
function saveTutorial(){try{localStorage.setItem(TUTORIAL_KEY,JSON.stringify({seen:tutorial.seen}));}catch{}}
function removeTutorialMarks(){document.querySelectorAll('.quick-tour-target').forEach(el=>el.classList.remove('quick-tour-target'));}
function stopTutorial(){tutorial.active=false;tutorial.seen=true;saveTutorial();removeTutorialMarks();$('quick-tour')?.remove();restoreSceneFocus();}
function scheduleTutorial(){if(tutorialFrame!==null)return;tutorialFrame=requestAnimationFrame(()=>{tutorialFrame=null;renderTutorial();});}
function tutorialIntro(){if(dialog.open)close();started=true;tutorial={active:true,seen:true,index:0};saveTutorial();render();}
function renderTutorial(){removeTutorialMarks();if(!tutorial.active||!started||dialog.open){$('quick-tour')?.remove();return;}let panel=$('quick-tour');if(!panel){panel=document.createElement('aside');panel.id='quick-tour';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Repères rapides dans la classe');document.body.append(panel);}const step=quickTour[tutorial.index];panel.innerHTML=`<div class="quick-tour-heading"><span>REPÈRES · ${tutorial.index+1} / ${quickTour.length}</span><button id="tour-skip" aria-label="Fermer le tutoriel">×</button></div><h2>${step.title}</h2><p>${step.text}</p><div class="quick-tour-actions"><button id="tour-prev" ${tutorial.index===0?'disabled':''}>← Précédent</button><button id="tour-next">${tutorial.index===quickTour.length-1?'C’est parti':'Suivant →'}</button></div>`;$('tour-skip').onclick=stopTutorial;$('tour-prev').onclick=()=>{tutorial.index--;renderTutorial();};$('tour-next').onclick=()=>{if(tutorial.index===quickTour.length-1)stopTutorial();else{tutorial.index++;renderTutorial();}};const target=document.querySelector(step.target);target?.classList.add('quick-tour-target');if(innerWidth<700)target?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});$('tour-next').focus({preventScroll:true});}
window.addEventListener('keydown',event=>{if(tutorial.active&&event.key==='Escape'){event.preventDefault();stopTutorial();}});
dialog.addEventListener('close',()=>{scheduleTutorial();restoreSceneFocus();});

function help(){open('Comment jouer',`<h2 id="dialog-title">Observez. Essayez. Comprenez.</h2><ol class="steps-list"><li>Cliquez sur Thomas, Brendan ou William pour découvrir le chapitre et son vocabulaire.</li><li>Explorez la pièce : l’objet qui réagit au survol ou au focus ouvre directement le jeu Ri7. Sur téléphone, touchez cet objet.</li><li>Suivez les consignes du jeu original. Le cours, les exercices et les notes sont directement accessibles dans la classe.</li><li>Utilisez les indices ou le carnet si vous hésitez. Parcourez les slides interactives du cours associé : slides terminées et exercices résolues débloquent ensemble la partie suivante. La vidéo et le son sont facultatifs. Chaque tuteur présente un objectif, aide à revoir une notion et propose un point de compréhension. Cliquez sur le personnage ou sur l’ordinateur pour le cours. Le cahier ouvre vos notes, la tablette les exercices, le panneau mural votre parcours et le livre Guide l’aide.</li></ol><p class="small-note">La partie se sauvegarde dans ce navigateur après chaque action. Vous pouvez tout faire au clavier avec Tab, Entrée et Échap. Les chapitres validés sont conservés ; une partie de jeu interrompue reprend au début.</p><div class="dialog-actions"><button class="secondary" id="restart-tutorial">Repères rapides</button><button class="secondary" id="reset">Recommencer la partie</button><button class="secondary" id="help-home">Retour à l’accueil</button><button class="primary" id="help-close">J’ai compris</button></div>`);$('restart-tutorial').onclick=tutorialIntro;$('help-close').onclick=close;$('reset').onclick=resetDialog;$('help-home').onclick=()=>{close();started=false;render();restoreSceneFocus();};}
function resetDialog(){open('Recommencer',`<h2 id="dialog-title">Repartir du premier indice ?</h2><p>Votre progression et les découvertes du carnet seront remplacées par une nouvelle partie sur cet appareil.</p><div class="dialog-actions"><button class="secondary" id="cancel-reset">Garder ma partie</button><button class="primary" id="confirm-reset">Oui, recommencer</button></div>`);$('cancel-reset').onclick=help;$('confirm-reset').onclick=()=>{stopTutorial();tutorial={active:false};saveTutorial();dialogueProgress={};saveDialogueProgress();state=initialState();started=false;selected=[];viewRoom='reception';saveProgress(state);render();close();};}
dialog.addEventListener('close',()=>{vnCleanup?.();vnCleanup=null;stopVideo();dialog.querySelectorAll('iframe').forEach(f=>f.remove());dialog.classList.remove('course-dialog');});
$('close-dialog').onclick=close;dialog.addEventListener('cancel',()=>{if(returnFocus?.isConnected)returnFocus.focus();});
$('courses').onclick=()=>courses();$('journal').onclick=()=>journal();$('map').onclick=map;$('help').onclick=help;
$('home').onclick=e=>{e.preventDefault();if(state.finished)finish();else{started=false;render();}};
$('sources').onclick=()=>courses();
render();
for(const room of Object.values(rooms)){const image=new Image();image.src=room.image;}

installViewportLayout();

installImmersiveMode();

